#!/usr/bin/env node
// Design-system usage audit. Generated by DS Generator - do not edit by hand.
// Node >= 18, no dependencies. Never modifies files. Exit 1 = findings, 0 = clean, 2 = usage error.
// Principle: when in doubt, do not report. Every finding must be something the contract proves.
import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { createHash } from "node:crypto";
import { dirname, join, relative, resolve, extname, sep } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
// <root>/.claude/skills/<name>/scripts/audit.mjs
const ROOT = resolve(HERE, "../../../..");

function fail(message) {
  process.stderr.write("audit: " + message + "\n");
  process.exit(2);
}

let C;
try {
  C = JSON.parse(readFileSync(join(HERE, "contract.json"), "utf8"));
} catch (e) {
  fail("cannot read contract.json next to this script (" + (e && e.message ? e.message : e) + ")");
}
const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
if (!isObj(C)) fail("invalid contract.json: expected an object");
C.primitiveAlternatives = C.primitiveAlternatives ?? {};
C.exports = C.exports ?? [];
C.packageFiles = C.packageFiles ?? {};
// tokens and exports are required: defaulting them to empty would report every var and import as unknown.
if (!isObj(C.tokens) || !isObj(C.primitiveAlternatives) || !isObj(C.packageFiles) ||
    !Array.isArray(C.exports) || !C.exports.every((x) => typeof x === "string")) {
  fail("invalid contract.json: tokens, primitiveAlternatives and packageFiles must be objects and exports an array of names");
}
C.varPrefix = typeof C.varPrefix === "string" && C.varPrefix ? C.varPrefix : "--";
// Optional: repo-relative files that ARE the design system (the starter project's tokens.css, which
// defines semantics as var(<primitive>)). Their declarations count; their contents are not usage.
C.systemFiles = C.systemFiles ?? [];
if (!Array.isArray(C.systemFiles) || !C.systemFiles.every((x) => typeof x === "string")) {
  fail("invalid contract.json: systemFiles must be an array of paths");
}

const argv = process.argv.slice(2);
const asJson = argv.includes("--json");
const quiet = argv.includes("--quiet");
const folderArg = argv.find((a) => !a.startsWith("--"));
const TARGET = folderArg ? resolve(process.cwd(), folderArg) : ROOT;
if (!existsSync(TARGET) || !statSync(TARGET).isDirectory()) fail("not a folder: " + (folderArg || TARGET));

const CODE = new Set([".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs"]);
const STYLE = new Set([".css", ".scss", ".sass", ".less"]);
const MARKUP = new Set([".vue", ".svelte", ".html", ".astro"]);
// Every directory starting with "." is skipped too (.claude, .git, .next, .svelte-kit, .nuxt, .vercel, ...).
const IGNORED = new Set(["node_modules", "dist", "build", "out", "coverage", "storybook-static"]);
// Declarations are also read from dot-folders (.storybook, .config, ...), except version control and
// generated output or caches, which only repeat what the sources declare.
const DOT_SKIPPED = new Set([".git", ".hg", ".svn", ".next", ".nuxt", ".svelte-kit", ".vercel", ".netlify",
  ".output", ".turbo", ".cache", ".parcel-cache", ".yarn", ".pnpm-store", ".vite", ".angular"]);
const MINIFIED = /\.min\.(?:js|css)$/i;
// Colours are not checked in test support code (test/spec/stories files are covered by TEST_FILE).
const TEST_DIRS = new Set(["__tests__", "__mocks__", "__fixtures__", "fixtures", "cypress", "e2e"]);
const MAX_BYTES = 1024 * 1024;
const PKG_ABS = C.packageDir ? resolve(ROOT, C.packageDir) : null;
const TEST_FILE = /\.(test|spec|stories)\.[^.]+$/;
const inPackage = (abs) => !!PKG_ABS && (abs === PKG_ABS || abs.startsWith(PKG_ABS + sep));
const SYSTEM_ABS = new Set(C.systemFiles.filter(Boolean).map((p) => resolve(ROOT, p)));

const HEX = /#(?:[0-9a-fA-F]{8}|[0-9a-fA-F]{6}|[0-9a-fA-F]{4}|[0-9a-fA-F]{3})(?![0-9a-zA-Z_-])/g;
const FUNC = /\b(?:rgba?|hsla?)\(\s*[^()]*\)/g;
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const VAR = new RegExp("var\\(\\s*(" + esc(C.varPrefix) + "[A-Za-z0-9_-]+)", "g");
// Also TS computed keys cast to a type: { ["--ds-x" as string]: value }.
const DECL = new RegExp("(" + esc(C.varPrefix) + "[A-Za-z0-9_-]+)[\"'`]?(?:\\s+as\\s+[^\\]\\n;{}:]+\\])?\\]?\\s*:", "g");
const SETPROP = new RegExp("setProperty\\(\\s*[\"'`](" + esc(C.varPrefix) + "[A-Za-z0-9_-]+)", "g");

// dotDirs: also enter dot-folders not in DOT_SKIPPED (declaration pass only; findings never come from them).
function walk(dir, out, withPackage, dotDirs = false) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return out; }
  for (const e of entries) {
    if (e.isSymbolicLink()) continue;
    const abs = join(dir, e.name);
    if (e.isDirectory()) {
      if (IGNORED.has(e.name) || (e.name.startsWith(".") && (!dotDirs || DOT_SKIPPED.has(e.name))) ||
          (!withPackage && inPackage(abs))) continue;
      walk(abs, out, withPackage, dotDirs);
    } else if (e.isFile()) {
      const ext = extname(e.name).toLowerCase();
      if (!CODE.has(ext) && !STYLE.has(ext) && !MARKUP.has(ext)) continue;
      if (MINIFIED.test(e.name) || (!withPackage && (inPackage(abs) || SYSTEM_ABS.has(abs)))) continue;
      try { if (statSync(abs).size > MAX_BYTES) continue; } catch { continue; }
      out.push(abs);
    }
  }
  return out;
}

const blank = (m) => m.replace(/[^\n]/g, " ");
function stripComments(text, ext) {
  let t = text.replace(/\/\*[\s\S]*?\*\//g, blank);
  if (MARKUP.has(ext)) t = t.replace(/<!--[\s\S]*?-->/g, blank);
  if (ext !== ".css") t = t.replace(/(^|[^:"'`\\])\/\/[^\n]*/gm, (m, p) => p + " ".repeat(m.length - p.length));
  return t;
}

function lineStarts(text) { const s = [0]; for (let i = 0; i < text.length; i++) if (text[i] === "\n") s.push(i + 1); return s; }
function pos(starts, idx) {
  let lo = 0, hi = starts.length - 1;
  while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (starts[mid] <= idx) lo = mid; else hi = mid - 1; }
  return { line: lo + 1, column: idx - starts[lo] + 1 };
}

function hex2(n) { return Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0"); }
function normalizeColor(raw) {
  const s = raw.trim().toLowerCase();
  if (s[0] === "#") {
    let h = s.slice(1);
    if (h.length === 3 || h.length === 4) h = [...h].map((c) => c + c).join("");
    if (h.length === 8 && h.endsWith("ff")) h = h.slice(0, 6);
    return /^[0-9a-f]{6}([0-9a-f]{2})?$/.test(h) ? "#" + h : null;
  }
  const m = /^(rgba?|hsla?)\(([^()]*)\)$/.exec(s);
  if (!m) return null;
  const parts = m[2].split(/[\s,\/]+/).filter(Boolean);
  if (parts.length < 3) return null;
  const alphaRaw = parts[3];
  const a = alphaRaw === undefined ? 1 : alphaRaw.endsWith("%") ? parseFloat(alphaRaw) / 100 : parseFloat(alphaRaw);
  let r, g, b;
  if (m[1].startsWith("rgb")) {
    if (parts.slice(0, 3).some((p) => p.endsWith("%"))) return null;
    [r, g, b] = parts.slice(0, 3).map(Number);
  } else {
    const hh = parseFloat(parts[0]), ss = parseFloat(parts[1]) / 100, ll = parseFloat(parts[2]) / 100;
    const k = (n) => (n + hh / 30) % 12, q = ss * Math.min(ll, 1 - ll);
    const f = (n) => ll - q * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
    [r, g, b] = [f(0) * 255, f(8) * 255, f(4) * 255];
  }
  if ([r, g, b, a].some((v) => Number.isNaN(v))) return null;
  return "#" + hex2(r) + hex2(g) + hex2(b) + (a >= 1 ? "" : hex2(a * 255));
}

const semanticByColor = new Map();
for (const [name, t] of Object.entries(C.tokens)) {
  if (!t || t.kind !== "semantic" || !t.light) continue;
  const list = semanticByColor.get(t.light) ?? [];
  list.push(name);
  semanticByColor.set(t.light, list);
}

function lev(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
}
function closest(name, pool) {
  const max = Math.max(2, Math.floor(name.length / 4));
  return pool.map((p) => [p, lev(name.toLowerCase(), p.toLowerCase())])
    .filter(([, d]) => d <= max).sort((x, y) => x[1] - y[1] || (x[0] < y[0] ? -1 : 1)).slice(0, 3).map(([p]) => p);
}

const findings = [];
const notes = [];
const seen = new Set();
const usage = {};
function add(type, rel, starts, idx, found, suggestions) {
  const key = rel + ":" + idx + ":" + type;
  if (seen.has(key)) return;
  seen.add(key);
  const { line, column } = pos(starts, idx);
  findings.push({ type, file: rel, line, column, found, suggestions });
}

function colorFinding(rel, starts, idx, raw) {
  if (/[${}]/.test(raw)) return; // interpolated, not a literal colour
  const n = normalizeColor(raw);
  if (n === null) return; // cannot prove it is a colour: stay silent
  if (n.length === 9 && n.endsWith("00")) return; // fully transparent: no token expresses it, not misuse
  const sug = (semanticByColor.get(n) ?? []).slice(0, 3).map((v) => "var(" + v + ")");
  add("hardcoded-color", rel, starts, idx, raw, sug);
}

// Declaration values only. The last of { } ; : before the match must be ':' (so a selector
// like "#fed {" is not a value), and the first of { } ; after it must not be '{' (so
// "a:hover #fed {" is not a value either). url(#id) references are not colours, values of custom
// properties ("--x: #fff", Tailwind @theme) are definitions, and var(--x, #fff) fallbacks are the
// author's safety net. `loose` = text that only might be CSS (an ordinary string): also skip
// short hex that looks like an id or a word.
function scanStyle(text, offset, rel, starts, loose) {
  for (const re of [HEX, FUNC]) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(text))) {
      const before = text.slice(0, m.index);
      // Only the tail of `before` is inspected below: testing the whole prefix per match is quadratic.
      if (/url\(\s*["']?$/.test(before.slice(-24))) continue;
      if (m[0][0] === "#" && /[\w\/&.%]/.test(before.charAt(before.length - 1))) continue; // fragment of a URL or an id, not a value
      const last = Math.max(before.lastIndexOf("{"), before.lastIndexOf("}"), before.lastIndexOf(";"), before.lastIndexOf(":"));
      if (last < 0 || before[last] !== ":") continue;
      const varAt = before.lastIndexOf("var(");
      if (varAt >= 0 && /^var\(\s*--[\w-]+\s*,[^()]*$/.test(before.slice(varAt))) continue; // fallback argument of var()
      const term = Math.max(before.lastIndexOf("{", last), before.lastIndexOf("}", last), before.lastIndexOf(";", last));
      if (before.slice(term + 1, last).trim().startsWith("--")) continue; // custom-property value
      if (loose && m[0][0] === "#" && looksNotAColor(m[0])) continue;
      const after = text.slice(m.index + m[0].length);
      const next = after.search(/[{};]/);
      if (next >= 0 && after[next] === "{") continue;
      colorFinding(rel, starts, offset + m.index, m[0]);
    }
  }
}

const WHOLE = /^\s*(#(?:[0-9a-fA-F]{8}|[0-9a-fA-F]{6}|[0-9a-fA-F]{4}|[0-9a-fA-F]{3})|(?:rgba?|hsla?)\([^()]*\))\s*$/;
const TW = /-\[(#[0-9a-fA-F]{3,8}|(?:rgba?|hsla?)\([^\]]*\))\]/g;
// A string right after these is an anchor / selector / id, not a colour.
const NAV_BEFORE = /(?:\b(?:href|to|xlink:href|xlinkHref|id|htmlFor|for|hash|selector)\s*[=:]\s*\{?\s*|\b(?:querySelector(?:All)?|getElementById|closest|matches|scrollTo|scrollIntoView|replaceState|pushState|navigate|push|replace)\(\s*)$/;
// A value right after a "--name" key or setProperty("--name", ...) defines a custom property.
const CUSTOM_PROP_BEFORE = /(?:(?:^|[^\w-])--[\w-]+["'`]?(?:\s+as\s+[^\]\n;{}:]+\])?\]?\s*:|setProperty\(\s*["'`]--[\w-]+["'`]\s*,)\s*$/;
const STRING = /(["'])((?:\\.|(?!\1)[^\\\n])*)\1|`((?:\\[\s\S]|[^\\`])*)`/g;

// A short (3-4 digit) hex that is either only letters ("#add", "#fed", "#bad") or only digits
// ("#123", "#2024") is far more likely to be an anchor, id or number than a colour. Repeated
// characters ("#fff", "#ccc", "#000", "#1111") are still colours.
function looksNotAColor(hex) {
  const h = hex.slice(1);
  if (h.length !== 3 && h.length !== 4) return false;
  if (/^(.)\1+$/.test(h)) return false;
  return !/[0-9]/.test(h) || /^[0-9]+$/.test(h);
}

// A template literal is scanned as full CSS only when its tag is a known CSS-in-JS one
// (styled.div`..`, styled.div<Props>`..`, styled(Button)`..`, css`..`, keyframes`..`,
// createGlobalStyle`..`, injectGlobal`..`). Other tags (Lit html, dedent, ...) and untagged
// literals go through the loose declaration-like path, so sentences such as `Error: see #1234`
// and HTML-in-template are left alone.
const CSS_TAG = /(?:\bcss|\bkeyframes|\bcreateGlobalStyle|\binjectGlobal|\bstyled(?:\.\w+|\([^)]*\))(?:\.attrs\([^)]*\))?(?:<[^>]*>)?)\s*$/;
function isTaggedTemplate(text, idx) {
  return CSS_TAG.test(text.slice(Math.max(0, idx - 200), idx));
}
const DECL_LIKE = /^\s*[a-z-]+\s*:(?!\/\/)/;

function scanCode(text, rel, starts) {
  STRING.lastIndex = 0;
  let m;
  while ((m = STRING.exec(text))) {
    const isTpl = m[3] !== undefined;
    const body = isTpl ? m[3] : m[2];
    const bodyAt = m.index + 1;
    const w = WHOLE.exec(body);
    if (w) {
      const near = text.slice(Math.max(0, m.index - 60), m.index);
      if (!NAV_BEFORE.test(near) && !CUSTOM_PROP_BEFORE.test(near) && !looksNotAColor(w[1])) {
        colorFinding(rel, starts, bodyAt + body.indexOf(w[1]), w[1]);
      }
      continue;
    }
    TW.lastIndex = 0;
    let t;
    while ((t = TW.exec(body))) colorFinding(rel, starts, bodyAt + t.index + 2, t[1]);
    if (isTpl && isTaggedTemplate(text, m.index)) scanStyle(body, bodyAt, rel, starts, false);
    else if (DECL_LIKE.test(body)) scanStyle(body, bodyAt, rel, starts, true);
  }
}

// Named exports of a barrel (same rules as parseExports in contract.ts). Anything that cannot be
// read with certainty makes the list incomplete.
const IDENT = "[A-Za-z_$][\\w$]*";
const EXPORT_LIST = /export\s+(?:type\s+)?\{([^}]*)\}/y;
const EXPORT_STAR_AS = new RegExp("export\\s+(?:type\\s+)?\\*\\s+as\\s+(" + IDENT + ")", "y");
const EXPORT_STAR = /export\s+(?:type\s+)?\*/y;
const EXPORT_DECL = new RegExp("export\\s+(?:declare\\s+)?(?:async\\s+)?(?:abstract\\s+)?(?:const\\s+enum|const|let|var|function\\s*\\*?|class|interface|type|enum|namespace)\\s*(" + IDENT + ")", "y");
const EXPORT_DEFAULT = /export\s+default\b/y;
function parseExports(source) {
  const text = source.replace(/\/\*[\s\S]*?\*\//g, " ").replace(/(^|[^:"'`\\])\/\/[^\n]*/gm, "$1");
  const names = new Set();
  let complete = true;
  const at = (re, idx) => { re.lastIndex = idx; return re.exec(text); };
  for (const m of text.matchAll(/\bexport\b/g)) {
    const idx = m.index;
    let r;
    if ((r = at(EXPORT_LIST, idx))) {
      for (const part of r[1].split(",")) {
        const spec = part.trim().replace(/^type\s+/, "");
        if (!spec) continue;
        const pieces = spec.split(/\s+as\s+/);
        const exported = pieces[pieces.length - 1].trim();
        if (exported && exported !== "default") names.add(exported);
      }
    } else if ((r = at(EXPORT_STAR_AS, idx))) names.add(r[1]);
    else if (at(EXPORT_STAR, idx)) complete = false;
    else if ((r = at(EXPORT_DECL, idx))) names.add(r[1]);
    else if (at(EXPORT_DEFAULT, idx)) { /* not importable by name */ }
    else complete = false;
  }
  return { names: [...names], complete };
}

function sha256(s) { return createHash("sha256").update(s.replace(/\r\n/g, "\n"), "utf8").digest("hex"); }

try {
  const cache = new Map();
  function load(abs) {
    if (cache.has(abs)) return cache.get(abs);
    let entry = null;
    try {
      const ext = extname(abs).toLowerCase();
      entry = { text: stripComments(readFileSync(abs, "utf8"), ext), ext };
    } catch { /* unreadable: skip */ }
    cache.set(abs, entry);
    return entry;
  }

  // Vars the client (or the package) declares anywhere in the repo are known, whatever folder is
  // being audited: declarations come from the whole repo plus the package, findings only from TARGET.
  const files = walk(TARGET, [], false);
  const texts = new Map();
  for (const abs of files) { const e = load(abs); if (e) texts.set(abs, e); }
  const customVars = new Set();
  const declFiles = new Set([...walk(ROOT, [], false, true), ...(PKG_ABS && existsSync(PKG_ABS) ? walk(PKG_ABS, [], true) : [])]);
  for (const abs of SYSTEM_ABS) {
    try { if (statSync(abs).isFile()) declFiles.add(abs); } catch { /* missing: nothing declared */ }
  }
  for (const abs of declFiles) {
    const e = load(abs);
    if (!e) continue;
    for (const re of [DECL, SETPROP]) {
      re.lastIndex = 0;
      let d;
      while ((d = re.exec(e.text))) customVars.add(d[1]);
    }
  }

  // Anchor: every publish rewrites CHANGELOG.md and the contract carries its hash. If the CHANGELOG
  // on disk is missing or different, this contract belongs to another publish (skills turned off
  // later, publish history reset, a publish that stopped half-way, or the CHANGELOG edited by hand):
  // it proves nothing about the package on disk, so neither hand edits nor unknown components are
  // reported. Checked whatever folder is audited: imports anywhere depend on it.
  const ANCHOR = "CHANGELOG.md";
  let anchorOk = true;
  if (PKG_ABS && typeof C.packageFiles[ANCHOR] === "string") {
    let log = null;
    try { log = readFileSync(join(PKG_ABS, ANCHOR), "utf8"); } catch { /* missing */ }
    anchorOk = log !== null && sha256(log) === C.packageFiles[ANCHOR];
    if (!anchorOk) {
      notes.push("Could not confirm that the agent skills match the package in this repo (its CHANGELOG.md is missing or differs from the one they were published with). Republish with agent skills enabled to refresh them. Hand-edit detection and unknown-component checks were skipped.");
    }
  }

  // Names the package on disk exports are never reported, whatever the contract says. A barrel that
  // cannot be read with certainty (`export *`, unusual syntax) may export anything: no unknown-component.
  const known = new Set(C.exports);
  let exportsCertain = C.exportsComplete === true && anchorOk;
  if (PKG_ABS) {
    let barrel = null;
    try { barrel = readFileSync(join(PKG_ABS, "components", "index.ts"), "utf8"); } catch { /* none */ }
    if (barrel !== null) {
      const disk = parseExports(barrel);
      if (disk.complete) for (const n of disk.names) known.add(n);
      else exportsCertain = false;
    }
  }

  const importSpecs = new Set(C.packageImport ? [C.packageImport, C.packageImport + "/components", C.packageImport + "/components/index"] : []);
  const IMPORT = /import\s+(?:type\s+)?(?:[\w$]+\s*,\s*)?\{([^}]*)\}\s*from\s*["']([^"']+)["']/g;
  const tokenNames = Object.keys(C.tokens);

  for (const [abs, { text, ext }] of texts) {
    const rel = relative(ROOT, abs).split(sep).join("/");
    const starts = lineStarts(text);
    const colorsOn = !TEST_FILE.test(abs) && !rel.split("/").slice(0, -1).some((seg) => TEST_DIRS.has(seg));

    if (colorsOn) {
      if (STYLE.has(ext)) scanStyle(text, 0, rel, starts);
      else if (MARKUP.has(ext)) {
        let rest = text;
        for (const s of text.matchAll(/(<style[^>]*>)([\s\S]*?)<\/style>/g)) {
          const at = s.index + s[1].length;
          scanStyle(s[2], at, rel, starts);
          rest = rest.slice(0, at) + blank(s[2]) + rest.slice(at + s[2].length);
        }
        scanCode(rest, rel, starts);
      } else scanCode(text, rel, starts);
    }

    VAR.lastIndex = 0;
    let v;
    while ((v = VAR.exec(text))) {
      const name = v[1];
      const at = v.index + v[0].indexOf(name);
      const tok = C.tokens[name];
      if (tok && tok.kind === "primitive") {
        add("primitive-token", rel, starts, at, name, (C.primitiveAlternatives[name] ?? []).map((s) => "var(" + s + ")"));
      } else if (!tok && C.varPrefix !== "--" && !customVars.has(name)) {
        const nextCh = text[v.index + v[0].length];
        if (/[-_]$/.test(name) || nextCh === "$" || nextCh === "{") continue; // dynamic name, e.g. var(--ds-color-${x})
        add("unknown-token", rel, starts, at, name, closest(name, tokenNames).map((s) => "var(" + s + ")"));
      }
    }

    if (CODE.has(ext) || MARKUP.has(ext)) {
      IMPORT.lastIndex = 0;
      let im;
      while ((im = IMPORT.exec(text))) {
        if (!importSpecs.has(im[2])) continue;
        let cursor = im.index + im[0].indexOf("{") + 1;
        for (const part of im[1].split(",")) {
          const name = part.trim().replace(/^type\s+/, "").split(/\s+as\s+/)[0].trim();
          const at = cursor + Math.max(0, part.indexOf(name));
          cursor += part.length + 1;
          if (!name || name === "default") continue;
          if (known.has(name)) usage[name] = (usage[name] ?? 0) + 1;
          else if (exportsCertain) add("unknown-component", rel, starts, at, name, closest(name, [...known]));
        }
      }
    }
  }

  // Hand edits: only when the audited folder contains the package and the anchor matches; missing
  // package files are never reported.
  const packageAudited = PKG_ABS && (PKG_ABS === TARGET || PKG_ABS.startsWith(TARGET + sep));
  if (packageAudited && anchorOk) {
    for (const [p, hash] of Object.entries(C.packageFiles)) {
      if (p === ANCHOR) continue; // the anchor is never reported as edited
      const abs = join(PKG_ABS, p);
      if (!existsSync(abs)) continue;
      let content;
      try { content = readFileSync(abs, "utf8"); } catch { continue; }
      if (sha256(content) !== hash) {
        findings.push({ type: "edited-package-file", file: relative(ROOT, abs).split(sep).join("/"), line: 1, column: 1, found: p,
          suggestions: ["Make this change in DS Generator and republish: local edits to the package are overwritten on the next publish."] });
      }
    }
  }

  const TYPES = ["hardcoded-color", "primitive-token", "unknown-token", "unknown-component", "edited-package-file"];
  const summary = Object.fromEntries(TYPES.map((t) => [t, findings.filter((f) => f.type === t).length]));
  process.exitCode = findings.length ? 1 : 0;

  if (asJson) {
    process.stdout.write(JSON.stringify({ system: C.system, version: C.version, root: ROOT, findings, summary, usage, notes }, null, 2) + "\n");
  } else {
    const fileCount = new Set(findings.map((f) => f.file)).size;
    const head = "Design system audit - " + C.system + " v" + C.version + ": " + findings.length + " findings in " + fileCount + " files";
    const lines = [head, ...notes.map((n) => "Note: " + n)];
    if (!quiet) {
      const LABEL = { "hardcoded-color": "Hard-coded colours", "primitive-token": "Primitive tokens used directly",
        "unknown-token": "Tokens that do not exist", "unknown-component": "Components the package does not export",
        "edited-package-file": "Package files edited by hand" };
      for (const t of TYPES) {
        const list = findings.filter((f) => f.type === t);
        if (!list.length) continue;
        lines.push("", "== " + LABEL[t] + " (" + list.length + ") ==");
        for (const f of list.slice(0, 50)) lines.push(f.file + ":" + f.line + ":" + f.column + "  " + f.found + (f.suggestions.length ? "  ->  " + f.suggestions.join(" | ") : ""));
        if (list.length > 50) lines.push("... and " + (list.length - 50) + " more (use --json)");
      }
      if (!findings.length) lines.push("No findings.");
    }
    process.stdout.write(lines.join("\n") + "\n");
  }
} catch (e) {
  fail("unexpected error (" + (e && e.message ? e.message : e) + ")");
}
